import numpy as np, scipy.sparse as sp, scipy.sparse.linalg as spla, random
N=300; density=0.01; k=5

def success(ncv, seeds=200):
    for seed in range(seeds):
        A=sp.random(N,N,density=density,format='csr',data_rvs=np.random.randn, random_state=seed)
        try:
            vals, vecs = spla.eigs(A,k=k,v0=np.ones(N),ncv=ncv,maxiter=N*50)  # reduced maxiter may speed but ??? we can still keep 6000 maybe to guarantee
        except Exception as e:
            return False
        pairs=sorted(zip(vals,vecs.T), key=lambda p:-abs(p[0]))
        vecs_comp=[p[1] for p in pairs]
        # compute Av - lambda v residual to verify quality
        for lam, v in zip([p[0] for p in pairs], vecs_comp):
            resid=np.linalg.norm(A.dot(v)-lam*v)
            if resid>1e-5:  # some threshold ensures good accuracy maybe
                return False
    return True

for ncv in range(10,16):
    print(ncv, success(ncv, 100))
