import numpy as np, scipy.sparse as sp, scipy.sparse.linalg as spla, random
k=5

def test(N, samples):
    for seed in random.sample(range(10**6), samples):
        A=sp.random(N,N,density=0.01,format='csr',data_rvs=np.random.randn, random_state=seed)
        try:
            vals, vecs = spla.eigs(A,k=k,v0=np.ones(N),ncv=20,maxiter=N*50,tol=1e-4)
        except Exception as e:
            print('no conv', N, seed)
            return False
        # compare
        vals_ref, vecs_ref = spla.eigs(A,k=k,v0=np.ones(N),ncv=20,maxiter=N*200)
        pairs1=sorted(zip(vals, vecs.T), key=lambda p:-abs(p[0])); cand=[p[1] for p in pairs1]
        pairs2=sorted(zip(vals_ref, vecs_ref.T), key=lambda p:-abs(p[0])); ref=[p[1] for p in pairs2]
        for c,e in zip(cand, ref):
            sim=abs(np.vdot(c,e))/(np.linalg.norm(c)*np.linalg.norm(e))
            if not np.isclose(sim,1.0, atol=1e-6):
                print('fail sim', N, seed, sim)
                return False
    return True

for N in [300,500,700,1000]:
    print(N, test(N, 50))
